    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LA_1LC1RD_0RB1LA_1RB0LA p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
