  - intros t Ht p _. apply fire_0RB1LA_1LC1RD_0RB1LA_1RB0LA. exact Ht.
  - exact wit_0RB1LA_1LC1RD_0RB1LA_1RB0LA.
  - apply qcleb_QC_05. reflexivity.
