Theorem qhtr_0RB1LA_1LC1RD_0RB1LA_1RB0LA : NonHalt tm_0RB1LA_1LC1RD_0RB1LA_1RB0LA /\ QHBoundTr 32779478 tm_0RB1LA_1LC1RD_0RB1LA_1RB0LA /\ QuasiHaltsTr tm_0RB1LA_1LC1RD_0RB1LA_1RB0LA.
