(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB1LA_1LC1RD_1LD1LB_1RB0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0;S1;S0]) [] j A0_0RB1LA_1LC1RD_1LD1LB_1RB0LA.
