Lemma lapi_0RB1LA_1LC1RD_1LD1LB_1RB0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
