             run_int_0RB1LA_1LC1RD_1LD1LB_1RB0LA (Jp q0 ++ [S0;S1;S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_0RB1LA_1LC1RD_1LD1LB_1RB0LA p j q0 E).
