  apply (fire_of_run_instr tm Cc false true l A0_0RB1LA_1LC1RD_1RD0LA_1RB0LA p j (Jp q0 ++ [S0;S1;S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_0RB1LA_1LC1RD_1RD0LA_1RB0LA p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1LA_1LC1RD_1RD0LA_1RB0LA : forall t, ~ In t pins_0RB1LA_1LC1RD_1RD0LA_1RB0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB1LA_1LC1RD_1RD0LA_1RB0LA.
