Theorem qhtrm_0RB1LA_1LC1RD_1RD0LA_1RB0LA : NonHalt tmm_0RB1LA_1LC1RD_1RD0LA_1RB0LA /\ QHBoundTr 32779478 tmm_0RB1LA_1LC1RD_1RD0LA_1RB0LA /\ QuasiHaltsTr tmm_0RB1LA_1LC1RD_1RD0LA_1RB0LA.
