  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LA_1LC1RD_1RD1RA_1RB0LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LA_1LC1RD_1RD1RA_1RB0LA B0_0RB1LA_1LC1RD_1RD1RA_1RB0LA B1_0RB1LA_1LC1RD_1RD1RA_1RB0LA 4 8 p j' [] []).
    + exact run_ovf_0RB1LA_1LC1RD_1RD1RA_1RB0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LA_1LC1RD_1RD1RA_1RB0LA p j' E).
    + exact (geo_0RB1LA_1LC1RD_1RD1RA_1RB0LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_0RB1LA_1LC1RD_1RD1RA_1RB0LA : stepn tmm_0RB1LA_1LC1RD_1RD1RA_1RB0LA 5 InitES = Some (lift (Cc 1)).
