(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_0RB1LA_1LC1RD_1RD1RA_1RB0LA : existsb (fun tg => cfires tmm_0RB1LA_1LC1RD_1RD1RA_1RB0LA c0 5 tg) pins_0RB1LA_1LC1RD_1RD1RA_1RB0LA = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1LA_1LC1RD_1RD1RA_1RB0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LA_1LC1RD_1RD1RA_1RB0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1LA_1LC1RD_1RD1RA_1RB0LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LA_1LC1RD_1RD1RA_1RB0LA p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_0RB1LA_1LC1RD_1RD1RA_1RB0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_0RB1LA_1LC1RD_1RD1RA_1RB0LA = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_0RB1LA_1LC1RD_1RD1RA_1RB0LA p j (Jp q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_0RB1LA_1LC1RD_1RD1RA_1RB0LA p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1LA_1LC1RD_1RD1RA_1RB0LA : forall t, ~ In t pins_0RB1LA_1LC1RD_1RD1RA_1RB0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB1LA_1LC1RD_1RD1RA_1RB0LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB1LA_1LC1RD_1RD1RA_1RB0LA
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB1LA_1LC1RD_1RD1RA_1RB0LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 3]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB1LA_1LC1RD_1RD1RA_1RB0LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB1LA_1LC1RD_1RD1RA_1RB0LA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB1LA_1LC1RD_1RD1RA_1RB0LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB1LA_1LC1RD_1RD1RA_1RB0LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D1: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_0RB1LA_1LC1RD_1RD1RA_1RB0LA (StD, S1)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_0RB1LA_1LC1RD_1RD1RA_1RB0LA [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
Qed.

Theorem qhtrm_0RB1LA_1LC1RD_1RD1RA_1RB0LA : NonHalt tmm_0RB1LA_1LC1RD_1RD1RA_1RB0LA /\ QHBoundTr 32779478 tmm_0RB1LA_1LC1RD_1RD1RA_1RB0LA /\ QuasiHaltsTr tmm_0RB1LA_1LC1RD_1RD1RA_1RB0LA.
Proof.
  apply (lap_qh_stage tmm_0RB1LA_1LC1RD_1RD1RA_1RB0LA pins_0RB1LA_1LC1RD_1RD1RA_1RB0LA Cc 1 5 32779478).
  - exact bootq_0RB1LA_1LC1RD_1RD1RA_1RB0LA.
  - intros p _. apply lap_0RB1LA_1LC1RD_1RD1RA_1RB0LA.
  - intros t Ht p _. apply fire_0RB1LA_1LC1RD_1RD1RA_1RB0LA. exact Ht.
  - exact wit_0RB1LA_1LC1RD_1RD1RA_1RB0LA.
  - apply qcleb_QC_05. reflexivity.
Qed.

Theorem qhtr_0RB1LA_1LC1RD_1RD1RA_1RB0LA : NonHalt tm_0RB1LA_1LC1RD_1RD1RA_1RB0LA /\ QHBoundTr 32779478 tm_0RB1LA_1LC1RD_1RD1RA_1RB0LA /\ QuasiHaltsTr tm_0RB1LA_1LC1RD_1RD1RA_1RB0LA.
