(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_0RB1LA_1RC0LA_1LD1RB_1LA1LC : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Jp q0 ++ [S0;S1;S0]) [] j A1_0RB1LA_1RC0LA_1LD1RB_1LA1LC) = lift (Cc (Pos.succ p)).
