    apply (lap_of_run tm Cc true true cho_0RB1LA_1RC0LA_1LD1RB_1LB1LC B0_0RB1LA_1RC0LA_1LD1RB_1LB1LC B1_0RB1LA_1RC0LA_1LD1RB_1LB1LC 4 16 p j' [] []).
