  - intros t Ht p _. apply fire_0RB1LA_1RC0LA_1LD1RB_1LB1LC. exact Ht.
  - exact wit_0RB1LA_1RC0LA_1LD1RB_1LB1LC.
  - apply qcleb_QC_05. reflexivity.
