Theorem qhtr_0RB1LA_1RC0LA_1LD1RB_1LB1LC : NonHalt tm_0RB1LA_1RC0LA_1LD1RB_1LB1LC /\ QHBoundTr 32779478 tm_0RB1LA_1RC0LA_1LD1RB_1LB1LC /\ QuasiHaltsTr tm_0RB1LA_1RC0LA_1LD1RB_1LB1LC.
