(** ** The lap *)

Lemma lap_0RB1LA_1RC0LA_1LD1RB_1RC1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
