    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LA_1RC0LA_1LD1RB_1RC1LC B0_0RB1LA_1RC0LA_1LD1RB_1RC1LC B1_0RB1LA_1RC0LA_1LD1RB_1RC1LC 4 16 p j' [] []).
    + exact run_ovf_0RB1LA_1RC0LA_1LD1RB_1RC1LC.
    + reflexivity.
